-- Owner 05.11: Artur fish (salmon steak, lightly salted salmon, butterfish) from 200 g in 50 g steps. Generated by src/artur.mjs arturFish200Sql().
UPDATE products SET profile=json_set(profile,'$.minimum_g',200,'$.order_step_g',50),version=version+1 WHERE id IN ('akhalkalaki--artur_salmon_steak','akhalkalaki--artur_salmon_salted','akhalkalaki--artur_butterfish') AND json_extract(profile,'$.mode')='WEIGHED' AND ((json_extract(profile,'$.minimum_g')=500 AND json_extract(profile,'$.order_step_g')=500) OR (json_extract(profile,'$.minimum_g')=300 AND json_extract(profile,'$.order_step_g')=100));
